/**
     * Parses the arguments according to the specified options and properties.
     *
     * @param options         The specified Options.
     * @param properties      command line option name-value pairs.
     * @param nonOptionAction see {@link NonOptionAction}.
     * @param arguments       The command line arguments.
     * @return The list of atomic option and value tokens.
     * @throws ParseException if there are any problems encountered while parsing the command line tokens.
     * @since 1.10.0
     */
public CommandLine parse(final Options options, final Properties properties, final NonOptionAction nonOptionAction, final String... arguments)
            throws ParseException {
        this.options = Objects.requireNonNull(options, "options");
        this.nonOptionAction = nonOptionAction;
        skipParsing = false;
        currentOption = null;
        expectedOpts = new ArrayList<>(options.getRequiredOptions());
        // clear the data from the groups
        for (final OptionGroup optionGroup : options.getOptionGroups()) {
            optionGroup.setSelected(null);
        }
        cmd = CommandLine.builder().setDeprecatedHandler(deprecatedHandler).get();
        if (arguments != null) {
            for (final String argument : arguments) {
                handleToken(argument);
            }
        }
        // check the arguments of the last option
        checkRequiredArgs();
        // add the default options
        handleProperties(properties);
        checkRequiredOptions();
        return cmd;
    }

/**
     * Removes the option or its group from the list of expected elements.
     *
     * @param option The option to remove from the list of expected elements.
     */
private void updateRequiredOptions(final Option option) throws AlreadySelectedException {
        if (option.isRequired()) {
            expectedOpts.remove(option.getKey());
        }
        // if the option is in an OptionGroup make that option the selected option of the group
        if (options.getOptionGroup(option) != null) {
            final OptionGroup optionGroup = options.getOptionGroup(option);
            if (optionGroup.isRequired()) {
                expectedOpts.remove(optionGroup);
            }
            optionGroup.setSelected(option);
        }
    }

/**
     * Parses the arguments according to the specified options and properties.
     *
     * @param options The specified Options.
     * @param arguments The command line arguments.
     * @param properties command line option name-value pairs.
     * @param stopAtNonOption if {@code true} an unrecognized argument stops the parsing and the remaining arguments
     *        are added to the {@link CommandLine}s args list. If {@code false} an unrecognized argument triggers a
     *        ParseException.
     * @return The list of atomic option and value tokens.
     * @throws ParseException if there are any problems encountered while parsing the command line tokens.
     * @since 1.1
     */
public CommandLine parse(final Options options, final String[] arguments, final Properties properties, final boolean stopAtNonOption)
            throws ParseException {
        // clear out the data in options in case it's been used before (CLI-71)
        options.helpOptions().forEach(Option::clearValues);
        // clear the data from the groups
        for (final OptionGroup optionGroup : options.getOptionGroups()) {
            optionGroup.setSelected(null);
        }
        // initialize members
        setOptions(options);
        cmd = CommandLine.builder().get();
        boolean eatTheRest = false;
        final List<String> tokenList = Arrays.asList(flatten(getOptions(), arguments == null ? Util.EMPTY_STRING_ARRAY : arguments, stopAtNonOption));
        final ListIterator<String> iterator = tokenList.listIterator();
        // process each flattened token
        while (iterator.hasNext()) {
            final String token = iterator.next();
            if (token != null) {
                // the value is the double-dash
                if (OptionFormatter.DEFAULT_LONG_OPT_PREFIX.equals(token)) {
                    eatTheRest = true;
                } else if (OptionFormatter.DEFAULT_OPT_PREFIX.equals(token)) {
                    // the value is a single dash
                    if (stopAtNonOption) {
                        eatTheRest = true;
                    } else {
                        cmd.addArg(token);
                    }
                } else if (token.startsWith(OptionFormatter.DEFAULT_OPT_PREFIX)) {
                    // the value is an option
                    if (stopAtNonOption && !getOptions().hasOption(token)) {
                        eatTheRest = true;
                        cmd.addArg(token);
                    } else {
                        processOption(token, iterator);
                    }
                } else {
                    // the value is an argument
                    cmd.addArg(token);
                    if (stopAtNonOption) {
                        eatTheRest = true;
                    }
                }
                // eat the remaining tokens
                if (eatTheRest) {
                    iterator.forEachRemaining(str -> {
                        // ensure only one double-dash is added
                        if (!OptionFormatter.DEFAULT_LONG_OPT_PREFIX.equals(str)) {
                            cmd.addArg(str);
                        }
                    });
                }
            }
        }
        processProperties(properties);
        checkRequiredOptions();
        return cmd;
    }

/**
     * Removes the option or its group from the list of expected elements.
     *
     * @param opt The option.
     */
private void updateRequiredOptions(final Option opt) throws ParseException {
        // if the option is a required option remove the option from
        // the requiredOptions list
        if (opt.isRequired()) {
            getRequiredOptions().remove(opt.getKey());
        }
        // if the option is in an OptionGroup make that option the selected
        // option of the group
        if (getOptions().getOptionGroup(opt) != null) {
            final OptionGroup optionGroup = getOptions().getOptionGroup(opt);
            if (optionGroup.isRequired()) {
                getRequiredOptions().remove(optionGroup);
            }
            optionGroup.setSelected(opt);
        }
    }

